"""Exact decimal arithmetic helpers (no precision limit, halves round up)."""
from __future__ import annotations

from decimal import (
    MAX_EMAX,
    MAX_PREC,
    MIN_EMIN,
    ROUND_HALF_UP,
    Context,
    Decimal,
)

CTX = Context(prec=MAX_PREC, Emax=MAX_EMAX, Emin=MIN_EMIN, rounding=ROUND_HALF_UP)
CENT = Decimal("0.01")
ZERO = Decimal("0.00")


def money(value: Decimal) -> Decimal:
    """Round to two places, halves up."""
    return value.quantize(CENT, rounding=ROUND_HALF_UP, context=CTX)


def fmt(value: Decimal) -> str:
    return format(value, "f")


def to_int(digits: str) -> int:
    """int() for a validated digit string, without the str->int digit limit."""
    return int(Decimal(digits))
"""The ``stockroom`` command."""
from __future__ import annotations

import csv
import errno
import io
import json
import os
import re
import sys
from typing import Callable, Dict, List, Optional, Tuple

from ._money import fmt
from .orders import invoice, order_key, shipped_quantities, status_of as order_status
from .parsing import (
    Movement,
    Order,
    ParseError,
    Product,
    first_negative,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_orders,
    valid_order_id,
    valid_sku,
)
from .pricing import Quote, price_order
from .shelves import available_on, history, signed, status_of, stock_levels

_QTY_ARG = re.compile(r"[0-9]+", re.ASCII)
_FORMATS = ("text", "csv", "json")
_USAGE = (
    "usage: stockroom [--dir DIR] COMMAND ...\n"
    "commands: stock, low, history SKU, receive DATE SKU QTY [NOTE], ship DATE SKU QTY [NOTE],\n"
    "          quote ORDER, fulfil ORDER DATE, invoice ORDER, report [--format text|csv|json]"
)


class _Fail(Exception):
    def __init__(self, code: int, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


def _usage(message: str) -> _Fail:
    return _Fail(2, "stockroom: %s\n%s" % (message, _USAGE))


# ---------------------------------------------------------------- command line


def _split_dir(argv: List[str]) -> Tuple[str, List[str]]:
    directory = "."
    rest: List[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise _usage("--dir needs a value")
            directory = argv[i + 1]
            i += 1
        elif arg.startswith("--dir="):
            directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        if not directory:
            raise _usage("--dir needs a value")
        i += 1
    return directory, rest


def _options(args: List[str], allow_json: bool, allow_format: bool) -> Tuple[List[str], bool, str]:
    positional: List[str] = []
    as_json = False
    fmt_name = "text"
    i = 0
    while i < len(args):
        arg = args[i]
        if not arg.startswith("-"):
            positional.append(arg)
        elif allow_json and arg == "--json":
            as_json = True
        elif allow_format and arg == "--format":
            if i + 1 >= len(args):
                raise _usage("--format needs a value")
            fmt_name = args[i + 1]
            i += 1
        elif allow_format and arg.startswith("--format="):
            fmt_name = arg[len("--format="):]
        else:
            raise _usage("unknown option %s" % arg)
        i += 1
    if fmt_name not in _FORMATS:
        raise _usage("bad --format value %r, expected text, csv or json" % fmt_name)
    return positional, as_json, fmt_name


def _date_arg(text: str):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise _usage(str(exc)) from None


# ---------------------------------------------------------------------- files


class _Dir:
    def __init__(self, directory: str) -> None:
        self.directory = directory

    def _text(self, name: str, required: bool) -> str:
        if not os.path.isdir(self.directory):
            raise _Fail(2, "stockroom: %s: not a directory" % self.directory)
        try:
            with open(os.path.join(self.directory, name), "rb") as handle:
                data = handle.read()
        except FileNotFoundError:
            if required:
                raise _Fail(2, "%s: file not found" % name) from None
            return ""
        except OSError as exc:
            raise _Fail(2, "%s: cannot read: %s" % (name, exc.strerror or exc)) from None
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError:
            raise _Fail(2, "%s: not valid UTF-8" % name) from None

    def _parsed(self, name: str, parse: Callable, *extra):
        text = self._text(name, name == "catalog.txt")
        try:
            return parse(text, *extra)
        except ParseError as exc:
            raise _Fail(1, "%s: %s" % (name, exc)) from None

    def catalog(self) -> Dict[str, Product]:
        return self._parsed("catalog.txt", parse_catalog)

    def movements(self, catalog) -> List[Movement]:
        return self._parsed("movements.txt", parse_movements, catalog)

    def orders(self, catalog) -> List[Order]:
        return self._parsed("orders.txt", parse_orders, catalog)

    def append(self, lines: List[str]) -> None:
        path = os.path.join(self.directory, "movements.txt")
        data = ("\n".join(lines) + "\n").encode("utf-8")
        try:
            try:
                with open(path, "rb") as handle:
                    handle.seek(0, os.SEEK_END)
                    if handle.tell():
                        handle.seek(-1, os.SEEK_END)
                        if handle.read(1) != b"\n":
                            data = b"\n" + data
            except FileNotFoundError:
                pass
            with open(path, "ab") as handle:
                handle.write(data)
        except OSError as exc:
            raise _Fail(2, "movements.txt: cannot write: %s" % (exc.strerror or exc)) from None


# --------------------------------------------------------------------- output


def _json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def _lines(rows: List[str]) -> str:
    return "".join(row + "\n" for row in rows)


def _find_sku(catalog, text: str) -> str:
    if valid_sku(text) and text.upper() in catalog:
        return text.upper()
    raise _Fail(1, "unknown SKU %r" % text)


def _find_order(orders: List[Order], text: str) -> Order:
    if valid_order_id(text):
        for order in orders:
            if order.id == text.upper():
                return order
    raise _Fail(1, "unknown order %r" % text)


def _quote_text(header: str, quote: Quote) -> str:
    rows = [header]
    for line in quote.lines:
        rows.append(" ".join([line.sku, str(line.quantity), fmt(line.unit), fmt(line.gross),
                              fmt(line.discount), fmt(line.net)]))
    rows += ["subtotal " + fmt(quote.subtotal), "order discount " + fmt(quote.order_discount),
             "tax " + fmt(quote.tax), "total " + fmt(quote.total)]
    return _lines(rows)


def _quote_json(order: Order, quote: Quote) -> str:
    return _json({
        "order": order.id,
        "date": order.date.isoformat(),
        "customer": order.customer,
        "lines": [{"sku": l.sku, "quantity": l.quantity, "unit": fmt(l.unit), "gross": fmt(l.gross),
                   "discount": fmt(l.discount), "net": fmt(l.net)} for l in quote.lines],
        "subtotal": fmt(quote.subtotal),
        "order_discount": fmt(quote.order_discount),
        "tax": fmt(quote.tax),
        "total": fmt(quote.total),
    })


def _header(order: Order) -> str:
    return "%s %s %s" % (order.id, order.date.isoformat(), order.customer)


# ------------------------------------------------------------------- commands


def _stock(d: _Dir, args: List[str], as_json: bool, _fmt: str) -> str:
    catalog = d.catalog()
    levels = stock_levels(catalog, d.movements(catalog))
    rows = [(sku, levels[sku], status_of(levels[sku], catalog[sku].reorder), catalog[sku].name)
            for sku in sorted(catalog)]
    if as_json:
        return _json([{"sku": s, "name": n, "onhand": o, "status": st} for s, o, st, n in rows])
    return _lines(["%s %d %s %s" % row for row in rows])


def _low(d: _Dir, args: List[str], as_json: bool, _fmt: str) -> str:
    catalog = d.catalog()
    levels = stock_levels(catalog, d.movements(catalog))
    rows = []
    for sku in sorted(catalog):
        reorder = catalog[sku].reorder
        if status_of(levels[sku], reorder) != "ok":
            rows.append((sku, levels[sku], reorder, max(1, 2 * reorder - levels[sku])))
    if as_json:
        return _json([{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in rows])
    return _lines(["%s %d %d %d" % row for row in rows])


def _history(d: _Dir, args: List[str], as_json: bool, _fmt: str) -> str:
    catalog = d.catalog()
    moves = d.movements(catalog)
    rows = history(_find_sku(catalog, args[0]), moves)
    if as_json:
        return _json([{"date": m.date.isoformat(), "delta": signed(m.quantity), "balance": b,
                       "note": m.note} for m, b in rows])
    return _lines([" ".join([m.date.isoformat(), signed(m.quantity), str(b)] + ([m.note] if m.note else []))
                   for m, b in rows])


def _move(sign: int) -> Callable:
    def run(d: _Dir, args: List[str], as_json: bool, _fmt: str) -> str:
        date = args[0]
        catalog = d.catalog()
        moves = d.movements(catalog)
        sku = _find_sku(catalog, args[1])
        if _QTY_ARG.fullmatch(args[2]) is None or int(args[2] or 0) == 0:
            raise _Fail(1, "bad quantity %r: expected a whole number of one or more" % args[2])
        note = args[3].strip(" \t") if len(args) == 4 else ""
        if "\n" in note or "\r" in note:
            raise _Fail(1, "note must not contain a line break")
        quantity = sign * int(args[2])
        move = Movement(parse_date(date), sku, quantity, note)
        bad = first_negative(moves + [move])
        if bad is not None:
            raise _Fail(1, "stock of %s would go below zero" % sku)
        line = "%s %s %s%s" % (date, sku, signed(quantity), " " + note if note else "")
        d.append([line])
        return line + "\n"
    return run


def _quote(d: _Dir, args: List[str], as_json: bool, _fmt: str) -> str:
    catalog = d.catalog()
    order = _find_order(d.orders(catalog), args[0])
    quote = price_order(order, catalog)
    return _quote_json(order, quote) if as_json else _quote_text(_header(order), quote)


def _fulfil(d: _Dir, args: List[str], as_json: bool, _fmt: str) -> str:
    catalog = d.catalog()
    moves = d.movements(catalog)
    order = _find_order(d.orders(catalog), args[0])
    date = parse_date(args[1])
    if date < order.date:
        raise _Fail(1, "cannot ship on %s: before the order date %s" % (args[1], order.date.isoformat()))
    before = shipped_quantities(order, moves)
    rows, added = [], []
    for (sku, qty), done in zip(order.lines, before):
        ship = min(qty - done, available_on(moves, sku, date))
        rows.append((sku, ship, qty - done - ship))
        if ship > 0:
            added.append("%s %s -%d order %s" % (args[1], sku, ship, order.id))
    if added:
        d.append(added)
    if all(owed == 0 for _, _, owed in rows):
        state = "complete"
    elif added or any(before):
        state = "partial"
    else:
        state = "open"
    return _lines(["%s shipped %d backordered %d" % row for row in rows] + ["status " + state])


def _invoice(d: _Dir, args: List[str], as_json: bool, _fmt: str) -> str:
    catalog = d.catalog()
    moves = d.movements(catalog)
    order = _find_order(d.orders(catalog), args[0])
    quote = invoice(order, moves, catalog)
    if quote is None:
        raise _Fail(1, "nothing shipped yet for %s" % order.id)
    return _quote_json(order, quote) if as_json else _quote_text("invoice " + _header(order), quote)


_REPORT_KEYS = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]


def _report(d: _Dir, args: List[str], as_json: bool, fmt_name: str) -> str:
    catalog = d.catalog()
    moves = d.movements(catalog)
    orders = d.orders(catalog)
    rows = []
    for order in sorted(orders, key=order_key):
        shipped = shipped_quantities(order, moves)
        billed = invoice(order, moves, catalog)
        rows.append([order.id, order.date.isoformat(), order.customer, order_status(order, shipped),
                     sum(q for _, q in order.lines), sum(shipped),
                     fmt(price_order(order, catalog).total), fmt(billed.total) if billed else "0.00"])
    if fmt_name == "json":
        return _json([dict(zip(_REPORT_KEYS, r)) for r in rows])
    if fmt_name == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(_REPORT_KEYS)
        writer.writerows(rows)
        return buffer.getvalue()
    return _lines(["%s %s %s %s %d/%d %s %s" % (r[0], r[1], r[2], r[3], r[5], r[4], r[6], r[7])
                   for r in rows])


# command: (handler, kind, positional counts); kind: "opts" parses --json/--format, "raw" does not
_COMMANDS = {
    "stock": (_stock, "opts", (0,)),
    "low": (_low, "opts", (0,)),
    "history": (_history, "opts", (1,)),
    "receive": (_move(1), "raw", (3, 4)),
    "ship": (_move(-1), "raw", (3, 4)),
    "quote": (_quote, "opts", (1,)),
    "fulfil": (_fulfil, "raw", (2,)),
    "invoice": (_invoice, "opts", (1,)),
    "report": (_report, "opts", (0,)),
}


def _run(argv: List[str]) -> str:
    directory, rest = _split_dir(argv)
    if not rest:
        raise _usage("no command given")
    name, args = rest[0], rest[1:]
    if name not in _COMMANDS:
        raise _usage("unknown command %r" % name)
    handler, kind, counts = _COMMANDS[name]
    as_json, fmt_name = False, "text"
    if kind == "opts":
        args, as_json, fmt_name = _options(args, name != "report", name == "report")
    if len(args) not in counts:
        raise _usage("%s takes %s argument(s), got %d" % (name, " or ".join(map(str, counts)), len(args)))
    if name in ("receive", "ship"):
        _date_arg(args[0])
        for arg in args:
            try:
                arg.encode("utf-8")
            except UnicodeEncodeError:
                raise _usage("argument is not valid UTF-8 text") from None
    elif name == "fulfil":
        _date_arg(args[1])
    return handler(_Dir(directory), args, as_json, fmt_name)


# ------------------------------------------------------------------ entry point


def _write_stderr(message: str) -> None:
    data = (message + "\n").encode("utf-8", "backslashreplace")
    try:
        err = sys.stderr
        buf = getattr(err, "buffer", None)
        if buf is not None:
            err.flush()
            buf.write(data)
            buf.flush()
        else:
            err.write(data.decode("utf-8"))
            err.flush()
    except (OSError, ValueError):
        pass


def _silence_stdout() -> None:
    try:
        fd = sys.stdout.fileno()
        null = os.open(os.devnull, os.O_WRONLY)
        os.dup2(null, fd)
        os.close(null)
    except Exception:  # noqa: BLE001 - nothing sensible left to do
        pass


def _emit(text: str) -> int:
    if not text:
        return 0
    out = sys.stdout
    try:
        buf = getattr(out, "buffer", None)
        if buf is not None:
            out.flush()
            buf.write(text.encode("utf-8", "replace"))
            buf.flush()
        else:
            out.write(text)
            out.flush()
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except OSError as exc:
        _silence_stdout()
        if exc.errno == errno.EPIPE:
            return 0
        _write_stderr("stockroom: cannot write output: %s" % (exc.strerror or exc))
        return 2
    return 0


def main(argv: Optional[List[str]] = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    limit = None
    if hasattr(sys, "set_int_max_str_digits"):
        limit = sys.get_int_max_str_digits()
        sys.set_int_max_str_digits(0)
    try:
        text = _run(args)
    except _Fail as fail:
        _write_stderr(fail.message)
        return fail.code
    finally:
        if limit is not None:
            sys.set_int_max_str_digits(limit)
    return _emit(text)
"""Order status: what has shipped so far, quotes and invoices."""
from __future__ import annotations

import dataclasses
from typing import Dict, List, Optional, Tuple

from .parsing import Movement, Order, Product
from .pricing import Quote, price_order


def shipped_quantities(order: Order, movements: List[Movement]) -> List[int]:
    """Per order line, units shipped so far (capped at the quantity ordered)."""
    note = "order " + order.id
    totals: Dict[str, int] = {}
    for move in movements:
        if move.quantity < 0 and move.note == note:
            totals[move.sku] = totals.get(move.sku, 0) - move.quantity
    return [min(qty, totals.get(sku, 0)) for sku, qty in order.lines]


def status_of(order: Order, shipped: List[int]) -> str:
    if all(done >= qty for (_, qty), done in zip(order.lines, shipped)):
        return "complete"
    return "partial" if any(shipped) else "open"


def invoice_order(order: Order, shipped: List[int]) -> Order:
    lines = [(sku, done) for (sku, _), done in zip(order.lines, shipped) if done > 0]
    return dataclasses.replace(order, lines=lines)


def invoice(order: Order, movements: List[Movement], catalog: Dict[str, Product]) -> Optional[Quote]:
    """Quote for what has shipped, or None when nothing has."""
    billed = invoice_order(order, shipped_quantities(order, movements))
    return price_order(billed, catalog) if billed.lines else None


def order_key(order: Order) -> Tuple:
    digits = order.id[3:].lstrip("0")
    return (order.date, len(digits), digits, order.id)
"""Parsing of catalog.txt, movements.txt and orders.txt."""
from __future__ import annotations

import datetime
import re
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Dict, Iterator, List, Optional, Tuple

from ._money import CENT, money, to_int

_WS = " \t"
_SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}", re.ASCII)
_PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?", re.ASCII)
_DIGITS_RE = re.compile(r"[0-9]+", re.ASCII)
_QTY_RE = re.compile(r"[+-]?[0-9]+", re.ASCII)
_ORDER_RE = re.compile(r"[Ss][Oo]-[0-9]+", re.ASCII)
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", re.ASCII)
_TOKEN_SPLIT = re.compile(r"[ \t]+")
_MOVE_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.S)
_TAXES = ("standard", "reduced", "zero")


class ParseError(ValueError):
    """A mistake in a data file; ``line`` is the 1-based line number."""

    def __init__(self, line: int, reason: str) -> None:
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str


@dataclass
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False, repr=False)


@dataclass
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]]


def records(text: str) -> Iterator[Tuple[int, str]]:
    """Yield (line number, trimmed content) for every non-blank, non-comment line."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        line = raw.strip(_WS)
        if line and not line.startswith("#"):
            yield number, line


def valid_sku(text: str) -> bool:
    return _SKU_RE.fullmatch(text) is not None


def valid_order_id(text: str) -> bool:
    return _ORDER_RE.fullmatch(text) is not None


def parse_date(text: str) -> datetime.date:
    """Parse YYYY-MM-DD; raise ValueError when it is not a real date."""
    if _DATE_RE.fullmatch(text) is None:
        raise ValueError("bad date %r, expected YYYY-MM-DD" % text)
    try:
        return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("bad date %r, no such day" % text) from None


def _date(number: int, text: str) -> datetime.date:
    try:
        return parse_date(text)
    except ValueError as exc:
        raise ParseError(number, str(exc)) from None


def parse_catalog(text: str) -> Dict[str, Product]:
    catalog: Dict[str, Product] = {}
    for number, line in records(text):
        fields = [f.strip(_WS) for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by |, got %d" % len(fields))
        sku, name, price, reorder = fields[:4]
        if not valid_sku(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "empty name")
        if _PRICE_RE.fullmatch(price) is None:
            raise ParseError(number, "bad price %r" % price)
        value = money(Decimal(price))
        if value < CENT:
            raise ParseError(number, "price must be at least 0.01")
        if _DIGITS_RE.fullmatch(reorder) is None:
            raise ParseError(number, "bad reorder level %r" % reorder)
        tax = fields[4].lower() if len(fields) == 5 else "standard"
        if tax not in _TAXES:
            raise ParseError(number, "bad tax %r, expected standard, reduced or zero" % tax)
        catalog[sku] = Product(sku, name, value, to_int(reorder), tax)
    return catalog


def first_negative(movements: List[Movement]) -> Optional[Movement]:
    """The first movement, in counting order, that takes its SKU below zero."""
    balances: Dict[str, int] = {}
    for move in sorted(movements, key=lambda m: m.date):
        balances[move.sku] = balances.get(move.sku, 0) + move.quantity
        if balances[move.sku] < 0:
            return move
    return None


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    moves: List[Movement] = []
    for number, line in records(text):
        match = _MOVE_RE.fullmatch(line)
        if match is None:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku, qty, note = match.groups()
        date = _date(number, date_text)
        if not valid_sku(sku) or sku.upper() not in catalog:
            raise ParseError(number, "unknown SKU %r" % sku)
        if _QTY_RE.fullmatch(qty) is None:
            raise ParseError(number, "bad quantity %r" % qty)
        quantity = to_int(qty)
        if quantity == 0:
            raise ParseError(number, "quantity must not be zero")
        moves.append(Movement(date, sku.upper(), quantity, (note or "").strip(_WS), number))
    bad = first_negative(moves)
    if bad is not None:
        raise ParseError(bad.line, "stock of %s would go below zero" % bad.sku)
    return moves


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    orders: List[Order] = []
    seen = set()
    for number, line in records(text):
        tokens = _TOKEN_SPLIT.split(line)
        if len(tokens) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES, got %d fields" % len(tokens))
        order_id, date_text, customer, spec = tokens
        if not valid_order_id(order_id):
            raise ParseError(number, "bad order id %r" % order_id)
        order_id = order_id.upper()
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        seen.add(order_id)
        date = _date(number, date_text)
        lines: List[Tuple[str, int]] = []
        used = set()
        for pair in spec.split(","):
            parts = pair.split("*")
            if len(parts) != 2 or not valid_sku(parts[0]) or _DIGITS_RE.fullmatch(parts[1]) is None:
                raise ParseError(number, "bad order line %r, expected SKU*QUANTITY" % pair)
            sku = parts[0].upper()
            if sku not in catalog:
                raise ParseError(number, "unknown SKU %r" % parts[0])
            if sku in used:
                raise ParseError(number, "SKU %s appears twice in the order" % sku)
            quantity = to_int(parts[1])
            if quantity < 1:
                raise ParseError(number, "quantity must be at least 1")
            used.add(sku)
            lines.append((sku, quantity))
        orders.append(Order(order_id, date, customer, lines))
    return orders
"""Order pricing: volume discount, order discount, per-line tax."""
from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal, localcontext
from typing import Dict, List

from ._money import CTX, ZERO, money
from .parsing import Order, Product

_RATES = {"standard": Decimal("0.20"), "reduced": Decimal("0.05"), "zero": Decimal("0")}
_ORDER_DISCOUNT_FROM = Decimal("500.00")


@dataclass
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def _negated(value: Decimal) -> Decimal:
    return -value if value else ZERO


def price_order(order: Order, catalog: Dict[str, Product]) -> Quote:
    with localcontext(CTX):
        lines: List[QuoteLine] = []
        for sku, quantity in order.lines:
            unit = catalog[sku].price
            gross = money(unit * quantity)
            if quantity >= 50:
                rate = Decimal("0.10")
            elif quantity >= 10:
                rate = Decimal("0.05")
            else:
                rate = Decimal("0")
            discount = _negated(money(gross * rate))
            lines.append(QuoteLine(sku, quantity, unit, gross, discount, gross + discount))
        subtotal = ZERO
        for line in lines:
            subtotal += line.net
        order_discount = ZERO
        if subtotal >= _ORDER_DISCOUNT_FROM:
            order_discount = _negated(money(subtotal * Decimal("0.03")))
        shares = _shares(lines, subtotal, order_discount)
        tax = ZERO
        for line, share in zip(lines, shares):
            taxable = line.net - Decimal(share).scaleb(-2)
            tax += money(taxable * _RATES[catalog[line.sku].tax])
        return Quote(lines, subtotal, order_discount, tax, subtotal + order_discount + tax)


def _shares(lines: List[QuoteLine], subtotal: Decimal, order_discount: Decimal) -> List[int]:
    """Order discount per line in pennies: floored, leftovers by largest remainder."""
    pennies = int(-order_discount * 100)
    if not pennies:
        return [0] * len(lines)
    whole = int(subtotal * 100)
    products = [pennies * int(line.net * 100) for line in lines]
    shares = [p // whole for p in products]
    remainders = [p % whole for p in products]
    leftover = pennies - sum(shares)
    for index in sorted(range(len(lines)), key=lambda i: (-remainders[i], i))[:leftover]:
        shares[index] += 1
    return shares
"""Stock levels, status, low list and history."""
from __future__ import annotations

import datetime
from typing import Dict, List, Tuple

from .parsing import Movement, Product


def stock_levels(catalog: Dict[str, Product], movements: List[Movement]) -> Dict[str, int]:
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def status_of(onhand: int, reorder: int) -> str:
    if onhand == 0:
        return "out"
    return "low" if onhand <= reorder else "ok"


def history(sku: str, movements: List[Movement]) -> List[Tuple[Movement, int]]:
    """Movements of one SKU in counting order, each with the balance after it."""
    rows = []
    balance = 0
    for move in sorted(movements, key=lambda m: m.date):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def available_on(movements: List[Movement], sku: str, date: datetime.date) -> int:
    """How many can leave on ``date`` without any later movement going negative."""
    balance = 0
    at_date = 0
    lowest = None
    for move in sorted(movements, key=lambda m: m.date):
        if move.sku != sku:
            continue
        balance += move.quantity
        if move.date <= date:
            at_date = balance
        else:
            lowest = balance if lowest is None else min(lowest, balance)
    return max(0, at_date if lowest is None else min(at_date, lowest))


def signed(quantity: int) -> str:
    return ("+%d" if quantity > 0 else "%d") % quantity

